import{_ as s,o as i,c as e,a4 as n}from"./chunks/framework.BRzJ4ijD.js";const d=JSON.parse('{"title":"分页、TLB、Huge Page","description":"","frontmatter":{},"headers":[],"relativePath":"os/memory/tlb-hugepage.md","filePath":"os/memory/tlb-hugepage.md","lastUpdated":1788475713000}'),t={name:"os/memory/tlb-hugepage.md"};function p(l,a,h,g,r,o){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="分页、tlb、huge-page" tabindex="-1">分页、TLB、Huge Page <a class="header-anchor" href="#分页、tlb、huge-page" aria-label="Permalink to &quot;分页、TLB、Huge Page&quot;">​</a></h1><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>页面大小<strong>是硬件工程师决定的硬件常数</strong>, 它决定了 TLB 的覆盖范围、cache line 数量、IO 单位, 同时直接影响用户程序性能. 但页大小不是任选的 —— 4 KB 是历史甜点, 大页是工程妥协, 这章把&quot;页大小为何是这个数字、改大会怎样、改小会怎样&quot; 一次讲清.</p><h2 id="页大小为什么是-4-kb" tabindex="-1">页大小为什么是 4 KB <a class="header-anchor" href="#页大小为什么是-4-kb" aria-label="Permalink to &quot;页大小为什么是 4 KB&quot;">​</a></h2><p>回头看上世纪 80 年代 VAX-11/780</p><ul><li>物理 RAM 几 MB;</li><li>寻址 32-bit, 4 GB 虚拟空间;</li><li>页表按 1 项 4 字节算: 4KB page = 1 M 项 × 4 = 4 MB 表 / process;</li><li>4 KB page + 4 MB 表 —— 把页表塞到一页可以放进 L1 cache 内, 极合理.</li></ul><p><strong>4 KB 是历史习惯的甜点</strong>, 同时这一常数一直被物化保留:</p><ul><li>x86 4 KB 一直保留;</li><li>OS page cache 一直按 4 KB;</li><li>NVMe 块层一直按 4 KB;</li><li>文件系统 metadata 一直按 4 KB;</li></ul><p>但 64-bit 时代虚拟空间暴涨、TLB 覆盖跟不上, <strong>huge page = x86 同时支持 2 MB / 1 GB 是补丁</strong>.</p><h2 id="tlb-覆盖范围" tabindex="-1">TLB 覆盖范围 <a class="header-anchor" href="#tlb-覆盖范围" aria-label="Permalink to &quot;TLB 覆盖范围&quot;">​</a></h2><p>TLB 是一个非常小的 cache (~128 entry). 它覆盖的内存量 = <code>entry 数 × page 大小</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>4 KB page, 128 entry TLB  → 覆盖 512 KB;</span></span>
<span class="line"><span>2 MB huge page, 128 entry → 覆盖 256 MB;</span></span>
<span class="line"><span>1 GB huge page, 128 entry → 覆盖 128 GB; (!)</span></span></code></pre></div><p>memory footprint &gt; covered range 时, TLB 持续 miss → page walk 频繁 → 全程被加 7~30 cycle 翻译延迟. 一次 page walk 通常: 4 级 × 几百 ps ≈ 几 ns, 但上层 cache miss 也会 = 几十 ns.</p><p><strong>这就是 huge page 的真正价值</strong>, 不是&quot;省内存&quot;, 而是把&quot;覆盖范围&quot; 抬高一 / 两个量级.</p><h2 id="三种-huge-page-模式" tabindex="-1">三种 huge page 模式 <a class="header-anchor" href="#三种-huge-page-模式" aria-label="Permalink to &quot;三种 huge page 模式&quot;">​</a></h2><h3 id="_1-显式-mmap-大页" tabindex="-1">1. 显式 mmap 大页 <a class="header-anchor" href="#_1-显式-mmap-大页" aria-label="Permalink to &quot;1. 显式 mmap 大页&quot;">​</a></h3><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mmap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, sz, PROT_READ</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PROT_WRITE,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">     MAP_PRIVATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MAP_ANONYMOUS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MAP_HUGETLB, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>要求 OS 配合: <code>echo N &gt; /proc/sys/vm/nr_hugepages</code> 预留大页池.</p><p><strong>缺点</strong>: 大页池是预留, 不使用也 占用, 不能跑普通程序. 需要管理员权限配置.</p><h3 id="_2-transparent-huge-page-thp" tabindex="-1">2. Transparent Huge Page (THP) <a class="header-anchor" href="#_2-transparent-huge-page-thp" aria-label="Permalink to &quot;2. Transparent Huge Page (THP)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo always &gt; /sys/kernel/mm/transparent_hugepage/enabled</span></span></code></pre></div><p>内核在后台同步把 4 KB 进程合并成 2 MB 大页. <strong>无需 app 适配, 但有如下坑</strong>:</p><ul><li>khugepaged 在后台扫描要 CPU, 1-5% 在大内存机器上看得到;</li><li>一旦扩容了, 拆回 4 KB 是 O(N) 反过来;</li><li>小内存进程 (几十 MB) 几乎无收益, 反而加回收代价;</li><li>HRT 场景下偶尔有 STALL.</li></ul><h3 id="_3-1-gb-大页-gbpage" tabindex="-1">3. 1 GB 大页 (gbpage) <a class="header-anchor" href="#_3-1-gb-大页-gbpage" aria-label="Permalink to &quot;3. 1 GB 大页 (gbpage)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>echo 5 &gt; /proc/sys/vm/nr_hugepages-1g  # 假写法, 看具体内核</span></span></code></pre></div><p><strong>只适合大内存 + 大数据集</strong>:</p><ul><li>HPC / ML 训练大 batch GPU memory pool;</li><li>大巨型 Redis cache (&gt;100 GB);</li><li>ML training 矢量库（vector db）.</li></ul><h2 id="huge-page-在查询热服务上的实测" tabindex="-1">huge page 在查询热服务上的实测 <a class="header-anchor" href="#huge-page-在查询热服务上的实测" aria-label="Permalink to &quot;huge page 在查询热服务上的实测&quot;">​</a></h2><p>Redis benchmark, NUMA 4-socket, 256 GB 内存, 1000 万键:</p><ul><li>4 KB page + 默认配置: QPS 250k, P99 0.9 ms;</li><li>THP enabled: QPS 320k, P99 0.4 ms;</li><li>显式 2 MB huge page mmap: QPS 340k, P99 0.35 ms.</li></ul><p>吞吐 30% 上升, 尾延迟 P99 减 60%. <strong>TLB 这一只性能的代价不可忽略</strong>.</p><h2 id="thunk-减少-page-walk-的-4-个工程-trick" tabindex="-1">thunk: 减少 page walk 的 4 个工程 trick <a class="header-anchor" href="#thunk-减少-page-walk-的-4-个工程-trick" aria-label="Permalink to &quot;thunk: 减少 page walk 的 4 个工程 trick&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 使用 huge page 提升覆盖范围;</span></span>
<span class="line"><span>2. 避免大 working set 跨 progress;</span></span>
<span class="line"><span>3. 内存局部化 (NUMA-aware allocation); </span></span>
<span class="line"><span>4. 拒绝频繁 mmap/munmap (TLB shootdown);</span></span></code></pre></div><h2 id="numa-与-huge-page-的协同" tabindex="-1">NUMA 与 huge page 的协同 <a class="header-anchor" href="#numa-与-huge-page-的协同" aria-label="Permalink to &quot;NUMA 与 huge page 的协同&quot;">​</a></h2><p>NUMA 节点 CPU 访问本地 vs 跨 socket 差 2-4×. huge page 落地哪个 socket 影响 cache.</p><ul><li><code>libnuma</code> / <code>mpol</code> 配 huge page 优先在本地 node 分配;</li><li>HPC 框架 <code>OpenMP + numactl --membind</code> / <code>mmap MAP_HUGETLB</code> 组合;</li><li>Go runtime GOGC + <code>GOMAXPROCS</code> 配 NODE 不要瞎选.</li></ul><h2 id="fpga-gpu-视角-huge-page-同构" tabindex="-1">FPGA / GPU 视角: huge page 同构 <a class="header-anchor" href="#fpga-gpu-视角-huge-page-同构" aria-label="Permalink to &quot;FPGA / GPU 视角: huge page 同构&quot;">​</a></h2><p>GPU 内存也是按一个&quot;页&quot; 概念. CUDA virtual mem management API 让你能 2 MB align, 减少跨 SM page swap. 类比 huge page 同构.</p><p>FPGA 上 BRAM 是固定 1-4 MB, 也可以做&quot;凑成&quot;大页-enable 的数据通路. <strong>每一层抽象都把&quot;页&quot; 当成 cache 单位的引擎</strong>, 让 TLB / cache / prefetcher 模型成立.</p><h2 id="调优现场" tabindex="-1">调优现场 <a class="header-anchor" href="#调优现场" aria-label="Permalink to &quot;调优现场&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查 TLB 基本信息</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/meminfo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> huge</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查进程是否用了 huge page</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /proc/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/smaps</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Huge</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 强制进程使用 huge page (THP)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> always</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /sys/kernel/mm/transparent_hugepage/enabled</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看 TLB miss 实际触发</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">perf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dTLB-loads,dTLB-load-misses,iTLB-loads,iTLB-load-misses</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./yourapp</span></span></code></pre></div><h2 id="this-带走的东西" tabindex="-1">this-&gt;带走的东西 <a class="header-anchor" href="#this-带走的东西" aria-label="Permalink to &quot;this-&gt;带走的东西&quot;">​</a></h2><ul><li>4 KB 是历史甜点, 64-bit 时代靠 huge page 补丁;</li><li>TLB 覆盖范围 = entry × page 大小, huge page 把覆盖率抬一个量级;</li><li>三种 huge page 模式有各自适用 / 性能脾气;</li><li>TLB shootdown 在多核 HPC 下是常见惊人延迟;</li><li>huge page 与 NUMA 协同才能彻底发挥.</li></ul><p>下一节 → <a href="./replacement">页面置换与 working set</a></p>`,44)])])}const c=s(t,[["render",p]]);export{d as __pageData,c as default};
